"""Combine the section reports into REPORT_draft.md. usage: report.py ARTDIR OUT.md"""
import glob
import json
import os
import sys


def first(art, name):
    g = glob.glob(os.path.join(art, "**", name), recursive=True)
    return open(g[0], encoding="utf-8").read() if g else f"_{name} missing (job failed or did not run)._\n"


def main():
    art, out = sys.argv[1], sys.argv[2]
    parts = ["# Round 4 media tests (repo 2, media/)", "",
             "Generated by `.github/workflows/media-r4.yml`. Datasets and weights were downloaded inside the jobs and "
             "never committed; artifacts carry numbers only.", ""]
    v = glob.glob(os.path.join(art, "**", "verify.json"), recursive=True)
    if v:
        d = json.load(open(v[0]))
        parts += ["## Verified models and datasets (from the files the jobs downloaded)", "",
                  "| repo | revision | declared licence |", "|---|---|---|"]
        for k, c in d.get("cards", {}).items():
            parts.append(f"| {k} | {str(c.get('sha', ''))[:10]} | {c.get('license', c.get('error', ''))} |")
        parts.append("")
        parts += ["| model file | MB | sha256 |", "|---|---|---|"]
        for f in d.get("files", []):
            if f["path"].endswith((".onnx", ".traineddata", ".bin", ".pth")):
                parts.append(f"| {f['path']} | {f['bytes'] / 1e6:.2f} | {(f['sha256'] or '')[:12]} |")
        if "docling_rs_manifest" in d:
            parts.append("")
            parts.append("docling.rs models-v1 manifest: " + "; ".join(
                f"{k}: {x['name']} ({x['license']})" for k, x in d["docling_rs_manifest"].items()))
        parts.append("")
    for name in ("ocr.md", "charts.md", "forms.md", "ffdetr.md", "ffdetr_match.md", "wordmath.md"):
        parts.append(first(art, name))
    open(out, "w", encoding="utf-8").write("\n".join(parts) + "\n")


if __name__ == "__main__":
    main()
